        // 专门用于根据提供的数据刷新UI的函数
        function refreshWithData(data) {
            var mapData = processJsonData(data);
            if (!mapData) {
                document.getElementById('map-title').textContent = "数据加载错误";
                return;
            }
            mapData.locations = adjustLayoutForOverlaps(mapData.locations);
            var pLoc = mapData.locations.find(function(l) { return l.name === mapData.protagonist.currentLocationName; });
            mapData.currentUserPosition = pLoc ? { x: pLoc.x + pLoc.width / 2, y: pLoc.y + pLoc.height / 2 } : null;
            renderMapInterface(mapData);

            var charContainer = document.getElementById('key-character-buttons');
            var charSection = document.getElementById('key-characters-section');
            charContainer.innerHTML = '';
            var hasChars = false;
            mapData.keyCharacters.forEach(function(c) {
                if (c.name) {
                    hasChars = true;
                    var btn = document.createElement('button');
                    btn.className = 'character-btn';
                    var icon = 'fa-question-circle'; // Default icon
                    if (c.isProtagonist) { icon = 'fa-user-astronaut'; }
                    else if (c.type === 'npc') { icon = 'fa-user-secret'; }
                    else if (c.type === 'reincarnator') { icon = 'fa-users'; }
                    btn.innerHTML = '<i class="fas ' + icon + '"></i> ' + c.name;
                    btn.onclick = function() { selectCharacter(c); };
                    charContainer.appendChild(btn);
                }
            });
            charSection.className = hasChars ? 'info-section' : 'info-section hidden';

            var extContainer = document.getElementById('external-area-buttons');
            var extSection = document.getElementById('external-areas-section');
            extContainer.innerHTML = '';
            if (mapData.externalAreas && mapData.externalAreas.length > 0) {
                extSection.classList.remove('hidden');
                mapData.externalAreas.forEach(function(a) {
                    var b = document.createElement('button');
                    b.className = 'area-btn';
                    b.innerHTML = '<i class="fas fa-globe"></i> ' + a;
                    b.onclick = function() { sendGameActionRequest('前往 ' + a); };
                    extContainer.appendChild(b);
                });
            } else {
                extSection.classList.add('hidden');
            }

            document.querySelectorAll('.modal-overlay .close-modal-button').forEach(function(b){b.onclick = function() { b.closest('.modal-overlay').classList.add('hidden'); }; });
            document.getElementById('shop-button').onclick = function() { openShopModal(mapData.shopItems, mapData.protagonist); };
            document.getElementById('reinforcement-button').onclick = function() { openReinforcementModal(mapData.reinforcements); };
            document.getElementById('storage-button').onclick = function() { openStorageModal(mapData.storageItems); };
            document.getElementById('task-button').onclick = function() { openTaskModal(mapData.tasks); };

            document.getElementById('alert-modal-ok-btn').onclick = function() { closeModal('alert-modal'); };
            document.getElementById('confirm-modal-cancel-btn').onclick = function() { closeModal('confirm-modal'); };
        }

        // Wait for the DOM to be ready before initializing
        document.addEventListener('DOMContentLoaded', function() {
            // 1. 立即执行首次加载
            runInitialization();

            // 2. 注册动态更新的回调函数
            if (dataSourceAPI && typeof dataSourceAPI.registerTableUpdateCallback === 'function') {
                dataSourceAPI.registerTableUpdateCallback(function(newData) {
                    console.log('Map received data update via callback from AutoCardUpdater, refreshing...', newData);
                    refreshWithData(newData);
                });
                console.log('Map update callback registered successfully with AutoCardUpdaterAPI.');
            } else {
                console.error('Failed to register map update callback. AutoCardUpdaterAPI might not be available on parent.');
            }

            // 3. (可选备用) 监听SillyTavern的核心聊天更新事件，以防回调遗漏
            // 根据文档，这是更现代和可靠的事件监听方式
            if (parent.SillyTavern && parent.SillyTavern.eventSource && typeof parent.SillyTavern.eventSource.on === 'function') {
                parent.SillyTavern.eventSource.on(parent.SillyTavern.eventTypes.CHAT_UPDATED, function() {
                    console.log('Map detected CHAT_UPDATED via SillyTavern event, re-initializing...');
                    runInitialization();
                });
                console.log('Standard chat update listener attached for fallback refresh.');
            }

            var mapContainer = document.getElementById('visual-map-container');
            var svg = document.getElementById('visual-map');
            var zoomInBtn = document.getElementById('zoom-in-btn');
            var zoomOutBtn = document.getElementById('zoom-out-btn');

            var viewBox = { x: 0, y: 0, w: 800, h: 600 };
            var isPanning = false;
            var startPoint = { x: 0, y: 0 };
            var endPoint = { x: 0, y: 0 };
            var scale = 1;

            function updateViewBox() {
                var vb = [viewBox.x, viewBox.y, viewBox.w, viewBox.h].join(' ');
                svg.setAttribute('viewBox', vb);
            }

            zoomInBtn.addEventListener('click', function() {
                var newWidth = viewBox.w * 0.9;
                var newHeight = viewBox.h * 0.9;
                viewBox.x += (viewBox.w - newWidth) / 2;
                viewBox.y += (viewBox.h - newHeight) / 2;
                viewBox.w = newWidth;
                viewBox.h = newHeight;
                updateViewBox();
            });

            zoomOutBtn.addEventListener('click', function() {
                var newWidth = viewBox.w * 1.1;
                var newHeight = viewBox.h * 1.1;
                viewBox.x += (viewBox.w - newWidth) / 2;
                viewBox.y += (viewBox.h - newHeight) / 2;
                viewBox.w = newWidth;
                viewBox.h = newHeight;
                updateViewBox();
            });

            function getPoint(e) {
                var point = e.touches ? e.touches[0] : e;
                return { x: point.clientX, y: point.clientY };
            }

            var panThreshold = 5; //
            var hasDragged = false;

            function onPanStart(e) {
                // e.preventDefault(); // Don't prevent default on start, as it can block clicks
                isPanning = true;
                hasDragged = false;
                startPoint = getPoint(e);
            }

            function onPanMove(e) {
                if (!isPanning) return;

                endPoint = getPoint(e);
                var moveX = Math.abs(startPoint.x - endPoint.x);
                var moveY = Math.abs(startPoint.y - endPoint.y);

                if (moveX > panThreshold || moveY > panThreshold) {
                    hasDragged = true;
                }

                if (hasDragged) {
                    e.preventDefault();
                    var dx = (startPoint.x - endPoint.x) * (viewBox.w / svg.clientWidth);
                    var dy = (startPoint.y - endPoint.y) * (viewBox.h / svg.clientHeight);
                    viewBox.x += dx;
                    viewBox.y += dy;
                    updateViewBox();
                    startPoint = endPoint;
                }
            }

            function onPanEnd(e) {
                isPanning = false;
            }

            svg.addEventListener('mousedown', onPanStart);
            svg.addEventListener('mousemove', onPanMove);
            svg.addEventListener('mouseup', onPanEnd);
            svg.addEventListener('mouseleave', onPanEnd);

            svg.addEventListener('touchstart', onPanStart);
            svg.addEventListener('touchmove', onPanMove);
            svg.addEventListener('touchend', onPanEnd);
            svg.addEventListener('touchcancel', onPanEnd);

            // Prevent click event on map locations if a drag occurred
            var mapLocations = document.querySelectorAll('.map-location-group');
            mapLocations.forEach(function(loc) {
                loc.addEventListener('click', function(e) {
                    if (hasDragged) {
                        e.preventDefault();
                        e.stopPropagation();
                    }
                }, true); // Use capture phase to intercept click early
            });
        });
    </script>
</body>
</html>
