        document.addEventListener('DOMContentLoaded', function() {
            var dataSourceAPI = parent.AutoCardUpdaterAPI;

            function getTableData() {
                try {
                    if (dataSourceAPI && typeof dataSourceAPI.exportTableAsJson === 'function') {
                        return dataSourceAPI.exportTableAsJson();
                    } else {
                        console.error("DataSource API (parent.AutoCardUpdaterAPI) not found or is invalid.");
                        return {};
                    }
                } catch (e) {
                    console.error("Error getting table data from DataSource API:", e);
                    return {};
                }
            }

            function refreshWithData(json) {
                var tablesByName = {};
                if (json && typeof json === 'object') {
                    for (var sheetId in json) {
                        // 确保是自身的属性，并且数据有效
                        if (Object.prototype.hasOwnProperty.call(json, sheetId) && json[sheetId] && json[sheetId].name) {
                            tablesByName[json[sheetId].name] = json[sheetId];
                        }
                    }
                }

                var title = '未知世界';
                var time = '时间同步中...';

                // 从名为'主神空间数据表'的表格中提取数据
                var globalTableData = tablesByName['主神空间数据表'];
                // 根据参照文件，数据在第二行（索引1），标题在第二列（索引1），时间在第五列（索引4）
                if (globalTableData && globalTableData.content && globalTableData.content.length > 1 && globalTableData.content[1]) {
                    var globalRow = globalTableData.content[1];
                    title = globalRow[1] || title;
                    time = globalRow[4] || time;
                }

                document.getElementById('main-title').textContent = title;
                document.getElementById('main-time').textContent = time;
            }

            function runInitialization() {
                var data = getTableData();
                refreshWithData(data);
            }

            runInitialization();

            if (dataSourceAPI && typeof dataSourceAPI.registerTableUpdateCallback === 'function') {
                dataSourceAPI.registerTableUpdateCallback(function(newData) {
                    console.log('Main content received data update, refreshing...', newData);
                    refreshWithData(newData);
                });
            }
        });
    </script>
</body>
</html>
