        .status-bar-hp { background-color: #ff4d4d; }
        .status-bar-sp { background-color: #4dff4d; }
        .status-bar-special { background-color: #4d4dff; }

        /* Shop & Task Modal Overhaul */
        .shop-item, .task-item {
            background: none; border: none; border-bottom: 1px dashed var(--border-color);
            padding: 15px 5px; margin-bottom: 10px; display: block;
        }
        .shop-item-header, .task-item-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px; }
        .shop-item-name, .task-item-name { font-family: var(--font-title); font-size: 1.2rem; color: var(--accent-cyan-main); }
        .shop-item-price { font-size: 1rem; color: var(--accent-magenta-main); font-weight: bold; }
        .shop-item-desc, .task-item-desc { font-size: 0.95rem; color: var(--text-medium-dim); margin-bottom: 10px; }
        .buy-button {
            background: transparent; border: 1px solid var(--accent-magenta-main); color: var(--accent-magenta-main);
            padding: 6px 12px; border-radius: var(--radius-base); cursor: pointer;
            transition: all 0.3s ease; float: right;
        }
        .buy-button:hover { background: var(--accent-magenta-main); color: var(--bg-dark-main); box-shadow: 0 0 10px var(--accent-magenta-glow); }
        .task-item-progress { color: var(--text-light-main); }

        .confirm-modal-dialog { text-align: center; }
        .confirm-modal-buttons { display: flex; justify-content: space-around; gap: 20px; margin-top: 20px; }
        .confirm-modal-buttons .interaction-button { flex-grow: 1; }
        .confirm-modal-buttons .interaction-button.confirm { background-color: var(--accent-magenta-main); color: var(--bg-dark-main); border-color: var(--accent-magenta-main); }
        .confirm-modal-buttons .interaction-button.confirm:hover { box-shadow: 0 0 10px var(--accent-magenta-glow); }

        @media (max-width: 600px) {
            body { padding: 5px; }
            .map-interface { padding: 10px; }
            .map-header h2 { font-size: 1.5rem; }
            .top-right-buttons { gap: 5px; }
            .function-btn { padding: 6px 10px; font-size: 0.9rem; }
            .function-btn .btn-text { display: none; } /* Hide text on mobile */
            #visual-map-container { height: 45vh; }
            .modal-dialog { width: 95%; padding: 15px; }
            .interaction-options-grid { grid-template-columns: 1fr; }
        }
    </style>
</head>
<body>
