    </div>

    <div id="character-modal" class="modal-overlay hidden"><div class="modal-dialog"><button class="close-modal-button">&times;</button><h4 id="modal-character-name"></h4><div id="modal-character-content" class="modal-content"></div><div id="modal-character-interactions" class="interaction-options-grid"></div></div></div>
    <div id="shop-modal" class="modal-overlay hidden"><div class="modal-dialog"><button class="close-modal-button">&times;</button><h4><i class="fas fa-store"></i> 兑换列表</h4><div id="shop-items-container" class="modal-content"></div></div></div>
    <div id="reinforcement-modal" class="modal-overlay hidden"><div class="modal-dialog"><button class="close-modal-button">&times;</button><h4><i class="fas fa-bolt"></i> 主角强化</h4><div id="reinforcement-items-container" class="modal-content"></div></div></div>
    <div id="storage-modal" class="modal-overlay hidden"><div class="modal-dialog"><button class="close-modal-button">&times;</button><h4><i class="fas fa-box-open"></i> 主角背包</h4><div id="storage-items-container" class="modal-content"></div></div></div>
