    <div id="alert-modal" class="modal-overlay hidden"><div class="modal-dialog confirm-modal-dialog"><h4>提示</h4><div id="alert-modal-text" class="modal-content"></div><div class="confirm-modal-buttons"><button id="alert-modal-ok-btn" class="interaction-button confirm">好的</button></div></div></div>
    <div id="main-location-modal" class="modal-overlay hidden"><div class="modal-dialog"><button class="close-modal-button">&times;</button><h4 id="modal-main-loc-name"></h4><div id="modal-main-loc-content" class="modal-content"></div><div id="modal-main-loc-actions" style="text-align: center; padding-top: 15px; margin-top: 15px; border-top: 1px solid var(--border-color);"></div></div></div>
    <div id="map-element-modal" class="modal-overlay hidden"><div class="modal-dialog"><button class="close-modal-button">&times;</button><h4 id="modal-element-name"></h4><div id="modal-element-description" class="modal-content"></div><div id="modal-element-interactions" class="interaction-options-grid"></div></div></div>

    <script>
        // ES5 compatible code, FULLY CORRECTED VERSION
        function checkOverlap(rect1, rect2) {
            var margin = 1;
            return (rect1.x < rect2.x + rect2.width + margin &&
                    rect1.x + rect1.width + margin > rect2.x &&
                    rect1.y < rect2.y + rect2.height + margin &&
                    rect1.y + rect1.height + margin > rect2.y);
        }

        function adjustLayoutForOverlaps(locations) {
            if (!locations || locations.length < 2) return locations;
            var iterations = 150, forceFactor = 0.5;
            for (var i = 0; i < iterations; i++) {
                for (var j = 0; j < locations.length; j++) {
                    for (var k = j + 1; k < locations.length; k++) {
                        var locA = locations[j], locB = locations[k];
                        if (checkOverlap(locA, locB)) {
                            var dx = (locA.x + locA.width / 2) - (locB.x + locB.width / 2);
                            var dy = (locA.y + locA.height / 2) - (locB.y + locB.height / 2);
                            var distance = Math.sqrt(dx * dx + dy * dy);
                            if (distance === 0) {
                                dx = (Math.random() - 0.5) * 0.1;
                                dy = (Math.random() - 0.5) * 0.1;
                                distance = Math.sqrt(dx * dx + dy * dy);
                            }
                            var overlapX = (locA.width / 2 + locB.width / 2) - Math.abs(dx);
                            var overlapY = (locA.height / 2 + locB.height / 2) - Math.abs(dy);
                            if (overlapX > 0 && overlapY > 0) {
                                var moveX = (dx / distance) * overlapX * forceFactor;
                                var moveY = (dy / distance) * overlapY * forceFactor;
                                locA.x += moveX; locA.y += moveY;
                                locB.x -= moveX; locB.y -= moveY;
                            }
                        }
                    }
                }
            }
            return locations;
        }

        var tableData = {};
        var mapData = null, selectedMain = null, selectedSub = null;
        var protagonistCanMove = true;

        // [核心改造] 仅适配新的数据库插件 (AutoCardUpdaterAPI)
        // 使用 parent 访问主窗口的 API 对象
        var dataSourceAPI = parent.AutoCardUpdaterAPI;

        function getTableData() {
            try {
                if (dataSourceAPI && typeof dataSourceAPI.exportTableAsJson === 'function') {
                    // 调用新插件的导出函数
                    return dataSourceAPI.exportTableAsJson();
                } else {
                    console.error("DataSource API (parent.AutoCardUpdaterAPI) not found or is invalid.");
                    return {};
                }
            } catch (e) {
                console.error("Error getting table data from DataSource API:", e);
                return {};
            }
        }

        // 初始化时获取一次数据
        tableData = getTableData();

        function completeMissingLocations(defined, undefined) {
            var margin = 20; // Reasonable margin
            var defaultWidth = 150, defaultHeight = 80;

            var placedLocations = [].concat(defined);

            if (placedLocations.length === 0 && undefined.length > 0) {
                var firstLoc = undefined.shift();
                firstLoc.x = 0;
                firstLoc.y = 0;
                firstLoc.width = defaultWidth;
                firstLoc.height = defaultHeight;
                placedLocations.push(firstLoc);
            } else if (placedLocations.length > 0) {
                // Calculate average size from existing locations for better consistency
                var totalW = 0, totalH = 0;
                placedLocations.forEach(function(l) { totalW += l.width; totalH += l.height; });
                defaultWidth = Math.max(100, totalW / placedLocations.length); // ensure a min width
                defaultHeight = Math.max(50, totalH / placedLocations.length); // ensure a min height
            }

            undefined.forEach(function(locToPlace) {
                var bestPosition = null;
                var minDistance = Infinity;

                var validPositions = [];

                placedLocations.forEach(function(placed) {
                    // Candidate positions around the 'placed' block
                    var candidates = [
                        { x: placed.x + placed.width + margin, y: placed.y }, // Right
                        { x: placed.x - defaultWidth - margin, y: placed.y }, // Left
                        { x: placed.x, y: placed.y + placed.height + margin }, // Bottom
                        { x: placed.x, y: placed.y - defaultHeight - margin }  // Top
                    ];

                    candidates.forEach(function(cand) {
                        var newRect = { x: cand.x, y: cand.y, width: defaultWidth, height: defaultHeight };
                        var isOverlapping = false;
                        for (var i = 0; i < placedLocations.length; i++) {
                            if (checkOverlap(newRect, placedLocations[i])) {
                                isOverlapping = true;
                                break;
                            }
                        }
                        if (!isOverlapping) {
                            validPositions.push(cand);
                        }
                    });
                });

                if (validPositions.length > 0) {
                    // Find the position closest to the origin (0,0)
                    validPositions.forEach(function(pos) {
                        var dist = Math.sqrt(pos.x * pos.x + pos.y * pos.y);
                        if (dist < minDistance) {
                            minDistance = dist;
                            bestPosition = pos;
                        }
                    });
                } else {
                    // Fallback: place it to the far right
                    var maxX = -Infinity;
                    placedLocations.forEach(function(l) { maxX = Math.max(maxX, l.x + l.width); });
                    bestPosition = { x: maxX + margin, y: 0 };
                }

                locToPlace.x = bestPosition.x;
                locToPlace.y = bestPosition.y;
                locToPlace.width = defaultWidth;
                locToPlace.height = defaultHeight;
                placedLocations.push(locToPlace);
            });

            return placedLocations;
        }

        function processJsonData(json) {
            var tablesByName = {};
            if (!json || typeof json !== 'object') {
                console.error("Invalid JSON data provided.");
                return { title: '数据加载错误', time: '', locations: [], keyCharacters: [], externalAreas: [], shopItems: [], reinforcements: [], storageItems: [], tasks: [], protagonist: {} };
            }
            for (var sheetId in json) {
                if (Object.prototype.hasOwnProperty.call(json, sheetId) && json[sheetId] && json[sheetId].name) {
                    tablesByName[json[sheetId].name] = json[sheetId];
                }
            }

            var data = { title: '未知世界', time: '时间同步中...', locations: [], keyCharacters: [], externalAreas: [], shopItems: [], reinforcements: [], storageItems: [], tasks: [], protagonist: {} };

            var globalTable = tablesByName['主神空间数据表'] ? tablesByName['主神空间数据表'].content : [];
            if (globalTable && globalTable.length > 1 && globalTable[1]) {
                var global = globalTable[1];
                data.title = global[1] || '未知世界';
                data.time = global[4] || '时间同步中...';
            }

            var pStatusTable = tablesByName['主角状态表'] ? tablesByName['主角状态表'].content : [];
            var protagonist = { isProtagonist: true, name: '主角', details: {}, interactions: [] };
            if (pStatusTable.length > 1 && pStatusTable[1]) {
                var p = pStatusTable[1];
                protagonist.name = p[1];
                protagonist.details = { 
                    '外貌描写': p[2], 
                    'HP': p[3], 
                    'SP': p[4], 
                    '特殊资源': p[5], 
                    '当前状态': p[6], 
                    '当前属性': p[7],
                    '奖励点': p[8],
                    '支线剧情': p[9]
                };
                protagonist.currentLocationName = p[10];
                if (p[11]) {
                    data.externalAreas = (p[11] || '').split(/[,，；;]/).map(function(s) { return s.trim(); }).filter(Boolean);
                }
                protagonist.interactions = [p[12], p[13], p[14], p[15]].filter(Boolean);
            }
            data.protagonist = protagonist;
            data.keyCharacters.push(protagonist); // Add protagonist to the list for easy access

            var keyCharsTable = tablesByName['任务世界关键角色'] ? tablesByName['任务世界关键角色'].content : [];
            keyCharsTable.slice(1).forEach(function(r) {
                if (!r || !r[1]) return;
                data.keyCharacters.push({ 
                    name: r[1], 
                    type: 'npc',
                    details: { '阵营':r[2], '外貌特征':r[3], '身份/能力':r[4], '性格特点':r[5], '背景故事':r[6], '与团队关系':r[7], '持有的重要物品': r[8], '当前状态':r[9], '核心想法':r[10] }, 
                    interactions: [], 
                    avatar: null
                });
            });

            var reincarnatorsTable = tablesByName['其他轮回者表'] ? tablesByName['其他轮回者表'].content : [];
            reincarnatorsTable.slice(1).forEach(function(r) {
                if (!r || !r[1]) return;
                data.keyCharacters.push({
                    name: r[1],
                    type: 'reincarnator',
                    details: { '阵营': r[2], '外貌描述': r[3], '过往经历': r[4], 'HP': r[5], 'SP': r[6], '特殊资源': r[7], '持有强化': r[8], '持有的重要物品': r[9], '当前状态': r[10], '所在地点': r[11], '当前想法': r[12] },
                    interactions: [] // Other reincarnators use fixed interactions by default
                });
            });

            var shopTable = tablesByName['兑换列表'] ? tablesByName['兑换列表'].content : [];
            shopTable.slice(1).forEach(function(r) { if(r&&r[1]) data.shopItems.push({ name: r[1], type: r[2], description: r[3], price: r[4] }); });

            var reinforcementTable = tablesByName['主角强化表'] ? tablesByName['主角强化表'].content : [];
            reinforcementTable.slice(1).forEach(function(r) { if(r&&r[1]) data.reinforcements.push({ name: r[1], type: r[2], level: r[3], effect: r[4] }); });

            var storageTable = tablesByName['主角背包表'] ? tablesByName['主角背包表'].content : [];
            storageTable.slice(1).forEach(function(r) { if(r&&r[1]) data.storageItems.push({ name: r[1], quantity: r[2], description: r[3], type: r[4] }); });

            var tasksTable = tablesByName['任务日志表'] ? tablesByName['任务日志表'].content : [];
            tasksTable.slice(1).forEach(function(r) { if(r&&r[1]) data.tasks.push({ name: r[1], type: r[2], publisher: r[3], description: r[4], progress: r[5] }); });

            var elementsByLocation = {};
            var elementsTable = tablesByName['地图元素表'] ? tablesByName['地图元素表'].content : [];
            elementsTable.slice(1).forEach(function(r) {
                if(r && r[1] && r[4]) {
                    var locName = r[4];
                    if(!elementsByLocation[locName]) elementsByLocation[locName] = [];
                    elementsByLocation[locName].push({ name: r[1], type: r[2], description: r[3], status: r[5], interactions: [r[6], r[7], r[8]].filter(Boolean) });
                }
            });

            var mainLocsTable = tablesByName['主要地点表'] ? tablesByName['主要地点表'].content : [];
            var definedLocations = [];
            var undefinedLocations = [];
            mainLocsTable.slice(1).forEach(function(r) {
                if (r && r[1]) {
                    var locationData = {
                        name: r[1],
                        description: r[6],
                        elements: elementsByLocation[r[1]] || []
                    };
                    var x = parseInt(r[2]), y = parseInt(r[3]), w = parseInt(r[4]), h = parseInt(r[5]);
                    if (!isNaN(x) && !isNaN(y) && !isNaN(w) && !isNaN(h)) {
                        locationData.x = x;
                        locationData.y = y;
                        locationData.width = w;
                        locationData.height = h;
                        definedLocations.push(locationData);
                    } else {
                        undefinedLocations.push(locationData);
                    }
                }
            });

            data.locations = completeMissingLocations(definedLocations, undefinedLocations);

            return data;
        }

        function renderMapInterface(data) {
            var svg = document.getElementById('visual-map');
            svg.innerHTML = '';
            if (!data.locations || data.locations.length === 0) { svg.setAttribute('viewBox', '0 0 800 600'); return; }
            var minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
            data.locations.forEach(function(l) { minX = Math.min(minX, l.x); minY = Math.min(minY, l.y); maxX = Math.max(maxX, l.x + l.width); maxY = Math.max(maxY, l.y + l.height); });
            var padding = Math.max((maxX - minX) * 0.1, (maxY - minY) * 0.1, 50);
            var vX = minX - padding, vY = minY - padding, vW = (maxX-minX)+(padding*2), vH=(maxY-minY)+(padding*2);
            svg.setAttribute('viewBox', vX + ' ' + vY + ' ' + vW + ' ' + vH);
            data.locations.forEach(function(l) {
                var g = document.createElementNS("http://www.w3.org/2000/svg", 'g');
                g.setAttribute('class', 'map-location-group');
                g.addEventListener('click', function() { openMainLocationModal(l); });
                var r = document.createElementNS("http://www.w3.org/2000/svg", 'rect');
                r.setAttribute('x', l.x); r.setAttribute('y', l.y); r.setAttribute('width', l.width); r.setAttribute('height', l.height); r.setAttribute('class', 'map-location-rect');
                var t = document.createElementNS("http://www.w3.org/2000/svg", 'text');
                t.setAttribute('x', l.x + l.width / 2); t.setAttribute('y', l.y + l.height / 2); t.setAttribute('class', 'map-location-label');
                t.textContent = l.name;
                g.appendChild(r); g.appendChild(t); svg.appendChild(g);
            });
            if (data.currentUserPosition) {
                var pulse = document.createElementNS("http://www.w3.org/2000/svg", 'circle');
                pulse.setAttribute('cx', data.currentUserPosition.x);
                pulse.setAttribute('cy', data.currentUserPosition.y);
                pulse.setAttribute('r', '8');
                pulse.setAttribute('fill', 'rgba(0, 255, 255, 0.7)');
                pulse.innerHTML = '<animate attributeName="r" from="8" to="20" dur="1.5s" begin="0s" repeatCount="indefinite"/><animate attributeName="opacity" from="1" to="0" dur="1.5s" begin="0s" repeatCount="indefinite"/>';
                svg.appendChild(pulse);

                var dot = document.createElementNS("http://www.w3.org/2000/svg", 'circle');
                dot.setAttribute('cx', data.currentUserPosition.x);
                dot.setAttribute('cy', data.currentUserPosition.y);
                dot.setAttribute('r', '8');
                dot.setAttribute('fill', 'red');
                dot.setAttribute('stroke', 'white');
                dot.setAttribute('stroke-width', '2');
                svg.appendChild(dot);
            }
        }

        function openModal(modalId, setupFn) { var modal = document.getElementById(modalId); if(setupFn) setupFn(modal); modal.classList.remove('hidden'); }
        function closeModal(modalId) { document.getElementById(modalId).classList.add('hidden'); }
        function sendGameActionRequest(msg) {
            // 优先使用 STscript 的 /setinput 命令
            if (typeof parent.triggerSlash === 'function') {
                try {
                    parent.triggerSlash('/setinput ' + msg);
                } catch(e) {
                    showCustomAlert(e.toString());
                }
            } else {
                // 如果 triggerSlash 不可用，则尝试直接操作父页面的输入框
                var input = parent.document.getElementById('send_textarea');
                if (input) {
                    input.value = msg;
                } else {
                    showCustomAlert('错误: 无法找到输入框。指令: ' + msg);
                }
            }
        }
        function showCustomAlert(msg) { openModal('alert-modal', function(m){m.querySelector('#alert-modal-text').textContent=msg;});}

        function openMainLocationModal(loc) {
            openModal('main-location-modal', function(m){
                m.querySelector('#modal-main-loc-name').textContent = loc.name;
                var c = m.querySelector('#modal-main-loc-content');
                c.innerHTML = '<p class="task-item-desc">' + (loc.description || '环境信息未知') + '</p>';

                if (loc.elements && loc.elements.length > 0) {
                    var title = document.createElement('div');
                    title.className = 'section-title';
                    title.style.marginTop = '20px';
                    title.textContent = '可互动元素';
                    c.appendChild(title);

                    var grid = document.createElement('div');
                    grid.className = 'interaction-options-grid';
                    loc.elements.forEach(function(el){
                        var b = document.createElement('button');
                        b.className = 'interaction-button';
                        b.textContent = el.name + ' (' + (el.status || '未知') + ')';
                        b.onclick = function() { closeModal('main-location-modal'); openMapElementModal(el, loc); };
                        grid.appendChild(b);
                    });
                    c.appendChild(grid);
                }

                var actionsContainer = m.querySelector('#modal-main-loc-actions');
                actionsContainer.innerHTML = ''; 

                var goToButton = document.createElement('button');
                goToButton.className = 'interaction-button';
                goToButton.textContent = '到这里去';
                goToButton.style.width = 'auto';
                goToButton.style.padding = '10px 25px';

                goToButton.onclick = function() {
                    sendGameActionRequest('前往 ' + loc.name);
                    closeModal('main-location-modal');
                };

                actionsContainer.appendChild(goToButton);
            });
        }
        function openMapElementModal(el, loc) {
            openModal('map-element-modal', function(m){
                m.querySelector('#modal-element-name').textContent = el.name;
                var d = m.querySelector('#modal-element-description');
                d.innerHTML = '<p>' + (el.description || '信息未知') + '</p>';
                var o = m.querySelector('#modal-element-interactions');
                o.innerHTML = '';
                if(el.interactions && el.interactions.length > 0){
                    el.interactions.forEach(function(i){
                        var b = document.createElement('button');
                        b.className = 'interaction-button';
                        b.textContent = i;
                        b.onclick = function() { 
                            var command = '在' + loc.name + ' ' + i;
                            sendGameActionRequest(command); 
                            closeModal('map-element-modal'); 
                        };
                        o.appendChild(b);
                    });
                } else {
                    o.innerHTML = '<p style="text-align:center;">无互动选项</p>';
