        function selectCharacter(char) {
            openModal('character-modal', function(m) {
                m.querySelector('#modal-character-name').textContent = char.name;
                var content = m.querySelector('#modal-character-content');
                content.innerHTML = '';
                var details = char.details || {};

                var statusMapping = { 'HP': 'hp', 'SP': 'sp', '特殊资源': 'special' };

                for (var key in details) {
                    if (Object.prototype.hasOwnProperty.call(details, key) && details[key]) {
                        // Check if the key corresponds to a status bar
                        if (statusMapping[key]) {
                            var value = parseInt(details[key]) || 0;
                            var percentage = Math.min(100, value);

                            var barContainer = document.createElement('div');
                            barContainer.innerHTML = '<strong>' + key + ':</strong> ' + details[key];

                            var statusBar = document.createElement('div');
                            statusBar.className = 'status-bar';

                            var statusBarInner = document.createElement('div');
                            statusBarInner.className = 'status-bar-inner status-bar-' + statusMapping[key];
                            statusBarInner.style.width = percentage + '%';

                            statusBar.appendChild(statusBarInner);
                            barContainer.appendChild(statusBar);
                            content.appendChild(barContainer);
                        } else {
                            var p = document.createElement('p');
                            p.innerHTML = '<strong>' + key + ':</strong> ' + details[key];
                            content.appendChild(p);
                        }
                    }
                }

                var interactionsContainer = m.querySelector('#modal-character-interactions');
                interactionsContainer.innerHTML = '';

                // If character is the protagonist, show dynamic interactions from data
                if (char.isProtagonist) {
                    if (char.interactions && char.interactions.length > 0) {
                        char.interactions.forEach(function(i){
                            var b = document.createElement('button');
                            b.className = 'interaction-button';
                            b.textContent = i;
                            b.onclick = function(){ sendGameActionRequest(i); closeModal('character-modal'); };
                            interactionsContainer.appendChild(b);
                        });
                    } else {
                        interactionsContainer.innerHTML = '<p style="text-align:center;">无互动选项</p>';
                    }
                    return; // End function here for protagonist
                }

                // For other characters, use fixed 4+4 interactions
                var fixedInteractions = {
                    '交谈': ['友好交谈', '打探情报', '威胁利诱', '情感交流'],
                    '攻击': ['全力攻击', '试探攻击', '使用技能', '瞄准弱点'],
                    '观察': ['分析能力', '探查装备', '感知意图', '寻找破绽'],
                    '行动': ['赠送物品', '请求组队', '发布指令', '保持距离']
                };

                for (var mainAction in fixedInteractions) {
                    if (Object.prototype.hasOwnProperty.call(fixedInteractions, mainAction)) {
                        var mainBtn = document.createElement('button');
                        mainBtn.className = 'interaction-button';
                        mainBtn.textContent = mainAction;

                        var subActionsContainer = document.createElement('div');
                        subActionsContainer.className = 'interaction-options-grid sub-actions';
                        subActionsContainer.style.display = 'none';

                        fixedInteractions[mainAction].forEach(function(subAction) {
                            var subBtn = document.createElement('button');
                            subBtn.className = 'interaction-button';
                            subBtn.textContent = subAction;
                            subBtn.onclick = function() {
                                var command = '对 ' + char.name + ' ' + subAction;
                                sendGameActionRequest(command);
                                closeModal('character-modal');
                            };
                            subActionsContainer.appendChild(subBtn);
