                        mainBtn.onclick = function(e) {
                            var parentWrapper = e.target.parentNode;
                            var allSubContainers = interactionsContainer.querySelectorAll('.sub-actions');
                            var currentSubContainer = parentWrapper.querySelector('.sub-actions');
                            var isOpening = currentSubContainer && currentSubContainer.style.display === 'none';

                            allSubContainers.forEach(function(container) {
                                container.style.display = 'none';
                            });

                            if (currentSubContainer && isOpening) {
                                currentSubContainer.style.display = 'grid';
