                infoContainer.innerHTML = '<span><i class="fas fa-coins"></i> 奖励点: <strong>' + points + '</strong></span>' + 
                                          '<span style="margin-left: 15px;"><i class="fas fa-scroll"></i> 支线剧情: <strong>' + quests + '</strong></span>';

                var c = m.querySelector('#shop-items-container');
                c.innerHTML = '';
                if (!items || items.length === 0) { c.innerHTML = '<p style="text-align:center;">兑换列表为空</p>'; return; }
                items.forEach(function(i) {
